import AppKit

/// The vectorscope slot's body (spec §11 GR-10, GR-31): a near-black square,
/// Cb running right and Cr up, the counts as a white log density; a faint
/// centre cross; the six 75 % targets as 7 pt boxes labelled R, Mg, B, Cy, G
/// and Yl, or, at a zoom that puts one off the plot, as a 6 pt rim tick on
/// the square's edge pointing toward it, labelled inside; the skin line from
/// the centre to the edge; and the zoom's three cells "1× 2× 4×" in the
/// bottom-right corner (`VectorscopeZoomCells`). No circles. The counts are
/// binned at the zoom by the kernel, so the drawing never scales them. The
/// slot keeps it square and centres it. An HLG trace's targets, rim ticks and
/// skin line are BT.2020's (spec §11 HD-15 (g)).
final class VectorscopeView: NSView {
    static let targetBox: CGFloat = 7
    static let crossArm: CGFloat = 6
    /// A rim tick's length, inward from the square's edge.
    static let rimTick: CGFloat = 6
    /// Fixed inks over the near-black square, the same in either appearance.
    static let graticule = NSColor(white: 1, alpha: 0.28)
    static let label = NSColor(white: 1, alpha: 0.6)

    var trace: VectorscopeTrace? {
        didSet {
            guard trace != oldValue else { return }
            image = trace.flatMap(Self.density)
            if let trace { signal = trace.signal }
            needsDisplay = true
        }
    }
    /// The matrix the targets and skin line are drawn on: the last trace's
    /// signal, kept while there is none (`.sdr` before any).
    var signal: ScopeSignal = .sdr {
        didSet {
            guard signal != oldValue else { return }
            needsDisplay = true
        }
    }
    /// The zoom the targets are drawn at and the cells show; the slot's.
    var zoom: Int = 1 {
        didSet {
            guard zoom != oldValue else { return }
            cells.zoom = zoom
            needsDisplay = true
        }
    }
    /// A click on a cell: that zoom.
    var onZoom: ((Int) -> Void)?
    let cells = VectorscopeZoomCells()
    private var image: CGImage?

    init() {
        super.init(frame: .zero)
        cells.onZoom = { [weak self] zoom in self?.onZoom?(zoom) }
        cells.translatesAutoresizingMaskIntoConstraints = false
        addSubview(cells)
        let inset = VectorscopeZoomCells.inset
        NSLayoutConstraint.activate([
            cells.trailingAnchor.constraint(equalTo: trailingAnchor, constant: -inset),
            cells.bottomAnchor.constraint(equalTo: bottomAnchor, constant: -inset),
            cells.widthAnchor.constraint(equalToConstant: VectorscopeZoomCells.size.width),
            cells.heightAnchor.constraint(equalToConstant: VectorscopeZoomCells.size.height),
        ])
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("VectorscopeView does not support NSCoder")
    }

    /// The point at the centre of bin (`cb`, `cr`) in the view.
    func point(cb: Int, cr: Int) -> NSPoint {
        let bin = bounds.width / CGFloat(VectorscopeTrace.bins)
        return NSPoint(
            x: bounds.minX + (CGFloat(cb) + 0.5) * bin, y: bounds.minY + (CGFloat(cr) + 0.5) * bin)
    }

    override func draw(_ dirtyRect: NSRect) {
        ScopeWell.fill(bounds, image: image)
        let centre = point(cb: VectorscopeTrace.centre, cr: VectorscopeTrace.centre)
        Self.graticule.setStroke()
        let cross = NSBezierPath()
        cross.lineWidth = 1
        cross.move(to: NSPoint(x: centre.x - Self.crossArm, y: centre.y))
        cross.line(to: NSPoint(x: centre.x + Self.crossArm, y: centre.y))
        cross.move(to: NSPoint(x: centre.x, y: centre.y - Self.crossArm))
        cross.line(to: NSPoint(x: centre.x, y: centre.y + Self.crossArm))
        cross.stroke()
        // The skin line, centre to edge, at its angle from +Cb.
        let angle = VectorscopeTrace.skinLineDegrees(for: signal) * .pi / 180
        let reach = bounds.width / 2
        let skin = NSBezierPath()
        skin.lineWidth = 1
        skin.move(to: centre)
        skin.line(
            to: NSPoint(
                x: centre.x + reach * CGFloat(cos(angle)), y: centre.y + reach * CGFloat(sin(angle))))
        skin.stroke()
        for target in VectorscopeTrace.targets(for: signal) {
            let text = NSAttributedString(
                string: target.name,
                attributes: [.font: DS.mono(9), .foregroundColor: Self.label])
            if let bins = VectorscopeTrace.targetBins(cb: target.cb, cr: target.cr, zoom: zoom) {
                drawBox(at: point(cb: bins.cb, cr: bins.cr), text: text, centre: centre)
            } else {
                drawRimTick(toward: (target.cb, target.cr), text: text, centre: centre)
            }
        }
    }

    /// A target on the plot: its box, the label beyond it, away from the
    /// centre.
    private func drawBox(at: NSPoint, text: NSAttributedString, centre: NSPoint) {
        let half = Self.targetBox / 2
        let box = NSBezierPath(rect: NSRect(
            x: at.x - half, y: at.y - half, width: Self.targetBox, height: Self.targetBox))
        box.lineWidth = 1
        box.stroke()
        let size = text.size()
        let dx = at.x - centre.x
        let dy = at.y - centre.y
        let length = max(1, hypot(dx, dy))
        let away = half + 2 + max(size.width, size.height) / 2
        drawLabel(text, centredAt: NSPoint(
            x: at.x + dx / length * away, y: at.y + dy / length * away))
    }

    /// A target off the plot (GR-31): a `rimTick` line from where the ray
    /// from the centre toward it meets the square's edge, inward, its label
    /// just inside the tick's inner end.
    private func drawRimTick(
        toward target: (cb: Double, cr: Double), text: NSAttributedString, centre: NSPoint
    ) {
        let length = max(hypot(target.cb, target.cr), 1e-9)
        let dx = CGFloat(target.cb / length)
        let dy = CGFloat(target.cr / length)
        func reach(_ d: CGFloat, _ low: CGFloat, _ high: CGFloat, _ from: CGFloat) -> CGFloat {
            abs(d) < 1e-9 ? .greatestFiniteMagnitude : ((d > 0 ? high : low) - from) / d
        }
        let edge = min(
            reach(dx, bounds.minX, bounds.maxX, centre.x),
            reach(dy, bounds.minY, bounds.maxY, centre.y))
        let inner = max(0, edge - Self.rimTick)
        let tick = NSBezierPath()
        tick.lineWidth = 1
        tick.move(to: NSPoint(x: centre.x + dx * edge, y: centre.y + dy * edge))
        tick.line(to: NSPoint(x: centre.x + dx * inner, y: centre.y + dy * inner))
        tick.stroke()
        let size = text.size()
        let at = max(0, inner - 2 - max(size.width, size.height) / 2)
        drawLabel(text, centredAt: NSPoint(x: centre.x + dx * at, y: centre.y + dy * at))
    }

    /// `text` centred at `point`, kept inside the square.
    private func drawLabel(_ text: NSAttributedString, centredAt point: NSPoint) {
        let size = text.size()
        let x = point.x - size.width / 2
        let y = point.y - size.height / 2
        text.draw(at: NSPoint(
            x: min(max(x, bounds.minX), bounds.maxX - size.width),
            y: min(max(y, bounds.minY), bounds.maxY - size.height)))
    }

    /// The counts as a 256 × 256 white-on-clear image, Cr bin 255 at the top.
    static func density(_ trace: VectorscopeTrace) -> CGImage? {
        let side = VectorscopeTrace.bins
        let peak = trace.counts.max() ?? 0
        guard peak > 0, trace.counts.count == side * side else { return nil }
        let scale = 1 / log(1 + Double(peak))
        var pixels = [UInt8](repeating: 0, count: side * side * 4)
        for cr in 0..<side {
            for cb in 0..<side {
                let count = trace.counts[cr * side + cb]
                guard count > 0 else { continue }
                let alpha = UInt8(min(255, (255 * log(1 + Double(count)) * scale).rounded()))
                let at = ((side - 1 - cr) * side + cb) * 4
                pixels[at] = alpha
                pixels[at + 1] = alpha
                pixels[at + 2] = alpha
                pixels[at + 3] = alpha
            }
        }
        return ScopeWell.image(pixels, side: side)
    }
}

/// The vectorscope's zoom cells (spec §11 GR-31): three `cell`-point squares
/// "1×", "2×" and "4×" sharing 1 pt borders, `inset` in from the square's
/// bottom-right corner, mono 9 in the well's fixed inks, the current zoom's
/// cell filled. A click on a cell is that zoom (`onZoom`); the slot keeps it.
final class VectorscopeZoomCells: NSView {
    static let cell: CGFloat = 16
    static let inset: CGFloat = 4
    /// Three cells, each neighbour sharing a 1 pt border.
    static let size = NSSize(
        width: CGFloat(VectorscopeTrace.zooms.count) * (cell - 1) + 1, height: cell)

    var zoom: Int = 1 {
        didSet {
            guard zoom != oldValue else { return }
            needsDisplay = true
        }
    }
    var onZoom: ((Int) -> Void)?

    init() {
        super.init(frame: .zero)
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("VectorscopeZoomCells does not support NSCoder")
    }

    /// Cell `index`'s rect: each starts on its left neighbour's right border.
    static func cellRect(_ index: Int) -> NSRect {
        NSRect(x: CGFloat(index) * (cell - 1), y: 0, width: cell, height: cell)
    }

    override func acceptsFirstMouse(for event: NSEvent?) -> Bool { true }

    override func draw(_ dirtyRect: NSRect) {
        for (index, value) in VectorscopeTrace.zooms.enumerated() {
            let rect = Self.cellRect(index)
            if value == zoom {
                VectorscopeView.graticule.setFill()
                rect.fill()
            }
            VectorscopeView.graticule.setStroke()
            let border = NSBezierPath(rect: rect.insetBy(dx: 0.5, dy: 0.5))
            border.lineWidth = 1
            border.stroke()
            let text = NSAttributedString(
                string: "\(value)×",
                attributes: [.font: DS.mono(9), .foregroundColor: VectorscopeView.label])
            let size = text.size()
            text.draw(at: NSPoint(
                x: rect.midX - size.width / 2, y: rect.midY - size.height / 2))
        }
    }

    override func mouseDown(with event: NSEvent) {
        let at = convert(event.locationInWindow, from: nil)
        let zooms = VectorscopeTrace.zooms
        guard let index = zooms.indices.first(where: { Self.cellRect($0).contains(at) })
        else { return }
        onZoom?(zooms[index])
    }
}
import AppKit

/// The histogram slot's body (spec §11 GR-10): a near-black well, levels
/// 0…255 left to right, each plane's height the log of its count normalised
/// to the peak over all four planes; R′, G′ and B′ as translucent tinted
/// fills, Y′ a white line on top.
final class HistogramView: NSView {
    /// The fills' inks, R′ first.
    static let fills: [NSColor] = [
        NSColor(srgbRed: 1, green: 0.3, blue: 0.3, alpha: 0.45),
        NSColor(srgbRed: 0.3, green: 1, blue: 0.3, alpha: 0.45),
        NSColor(srgbRed: 0.4, green: 0.55, blue: 1, alpha: 0.45),
    ]

    var trace: HistogramTrace? {
        didSet {
            guard trace != oldValue else { return }
            needsDisplay = true
        }
    }

    override func draw(_ dirtyRect: NSRect) {
        WaveformTraceView.well.setFill()
        bounds.fill()
        guard let trace, let peak = trace.counts.max(), peak > 0 else { return }
        let scale = 1 / log(1 + Double(peak))
        let levels = WaveformTrace.levels
        let step = bounds.width / CGFloat(levels)
        /// Each level's height in the well.
        func heights(_ plane: Int) -> [CGFloat] {
            trace.plane(plane).map { CGFloat(log(1 + Double($0)) * scale) * bounds.height }
        }
        for plane in 0..<3 {
            let path = NSBezierPath()
            path.move(to: NSPoint(x: bounds.minX, y: bounds.minY))
            for (level, height) in heights(plane).enumerated() {
                let x = bounds.minX + CGFloat(level) * step
                path.line(to: NSPoint(x: x, y: bounds.minY + height))
                path.line(to: NSPoint(x: x + step, y: bounds.minY + height))
            }
            path.line(to: NSPoint(x: bounds.maxX, y: bounds.minY))
            path.close()
            Self.fills[plane].setFill()
            path.fill()
        }
        let luma = NSBezierPath()
        luma.lineWidth = 1.5
        for (level, height) in heights(3).enumerated() {
            let x = bounds.minX + CGFloat(level) * step
            let y = min(bounds.maxY - 0.75, bounds.minY + height)
            if level == 0 {
                luma.move(to: NSPoint(x: x, y: y))
            } else {
                luma.line(to: NSPoint(x: x, y: y))
            }
            luma.line(to: NSPoint(x: x + step, y: y))
        }
        NSColor.white.setStroke()
        luma.stroke()
    }
}
import AppKit

/// One slot of the scopes panel: a header with the picker at its left and
/// the faint caption at its right — "Rec. 709 · encoded", or in an HLG
/// project "HLG · cd/m²" or "Rec. 2100 HLG" (spec §11 HD-15 (f)), following
/// the signal of the last trace shown — the picked scope's
/// body, and — for the waveform and the histogram — the two clipping
/// readouts. Its height is its kind's chrome plus `bodyHeight`, which the
/// panel's layout rule sets. It also holds the vectorscope's zoom (spec §11
/// GR-31), which outlives a pick of another scope: its pass is `pass`.
final class ScopeSlotView: NSView {
    static let inset: CGFloat = 12
    static let headerTop: CGFloat = 10
    static let gap: CGFloat = 8
    static let readoutHeight: CGFloat = 15
    static let readoutGap: CGFloat = 4
    static let bottomPad: CGFloat = 8
    /// The body's width inside the insets.
    static let bodyWidth = ScopesPanelView.width - 2 * inset
    static let caption = "Rec. 709 · encoded"

    /// Owner choice 4: Waveform 200, Parade 200, Vectorscope a 224 pt
    /// square, Histogram 140.
    static func preferredBodyHeight(for kind: ScopeKind) -> CGFloat {
        switch kind {
        case .waveform, .parade: return 200
        case .vectorscope: return bodyWidth
        case .histogram: return 140
        }
    }

    /// Whether `kind` shows the two clipping readouts under its body.
    static func hasReadouts(_ kind: ScopeKind) -> Bool {
        kind == .waveform || kind == .histogram
    }

    /// Everything in the slot but the body: the header, the gaps, the
    /// readouts when the kind has them, the bottom pad.
    static func chromeHeight(for kind: ScopeKind) -> CGFloat {
        let readouts = hasReadouts(kind) ? gap + 2 * readoutHeight + readoutGap : 0
        return headerTop + DS.controlHeight + gap + readouts + bottomPad
    }

    let name: String
    /// What the picker chose; setting it puts that kind's body in.
    var kind: ScopeKind = .waveform {
        didSet {
            guard kind != oldValue else { return }
            installBody()
        }
    }
    /// The body's height from the panel's rule; a vectorscope's square side
    /// is min(`bodyWidth`, it).
    var bodyHeight: CGFloat = 0 {
        didSet {
            guard bodyHeight != oldValue else { return }
            applyHeights()
        }
    }
    var onPick: ((ScopeKind) -> Void)?
    /// The vectorscope's zoom (1, 2 or 4), pushed into a vectorscope body and
    /// kept across a pick of another scope and back.
    var zoom: Int = 1 {
        didSet {
            guard zoom != oldValue else { return }
            (body as? VectorscopeView)?.zoom = zoom
        }
    }
    /// A click on the vectorscope's zoom cells.
    var onZoom: ((Int) -> Void)?
    /// The pass this slot shows: its kind and, for the vectorscope, its zoom.
    var pass: ScopePass { ScopePass(kind, zoom: zoom) }
    /// The last trace's signal, kept across a pick and a frameless show; it
    /// sets the caption and a new body's scale.
    private(set) var signal: ScopeSignal = .sdr
    private(set) var body: NSView = WaveformTraceView()

    private lazy var picker = OptionPopupControl(
        width: 120, items: ScopeKind.allCases.map(\.title),
        read: { [weak self] in
            self.flatMap { ScopeKind.allCases.firstIndex(of: $0.kind) } ?? 0
        },
        write: { [weak self] index in self?.onPick?(ScopeKind.allCases[index]) },
        enabled: { true },
        // A pick redraws the picker through `kind`'s `installBody`.
        onEdit: {})
    private let captionLabel = NSTextField(labelWithString: ScopeSlotView.caption)
    private let highlights = NSTextField(labelWithString: WaveformTrace.noHighlights)
    private let shadows = NSTextField(labelWithString: WaveformTrace.noShadows)
    private var bodyConstraints: [NSLayoutConstraint] = []
    private var heightConstraint: NSLayoutConstraint?
    private var readoutTop: NSLayoutConstraint?

    init(name: String) {
        self.name = name
        super.init(frame: .zero)
        setAccessibilityIdentifier("scopes.\(name)")
        build()
        installBody()
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("ScopeSlotView does not support NSCoder")
    }

    /// `trace` drawn in the body (nil, or another kind's, is "no frame yet").
    func show(_ trace: ScopeTrace?) {
        if let trace, trace.kind == kind {
            signal = trace.signal
            captionLabel.stringValue = signal.caption(for: kind)
        }
        var readouts: (String, String)?
        switch (trace, body) {
        case (.waveform(let t)?, let view as WaveformTraceView):
            view.trace = t
            readouts = (t.highlightsReadout, t.shadowsReadout)
        case (.parade(let t)?, let view as ParadeView):
            view.trace = t
        case (.vectorscope(let t)?, let view as VectorscopeView):
            view.trace = t
        case (.histogram(let t)?, let view as HistogramView):
            view.trace = t
            readouts = (t.highlightsReadout, t.shadowsReadout)
        default:
            clearBody()
        }
        highlights.stringValue = readouts?.0 ?? WaveformTrace.noHighlights
        shadows.stringValue = readouts?.1 ?? WaveformTrace.noShadows
    }

    private func clearBody() {
        (body as? WaveformTraceView)?.trace = nil
        (body as? ParadeView)?.trace = nil
        (body as? VectorscopeView)?.trace = nil
        (body as? HistogramView)?.trace = nil
    }

    private func build() {
        captionLabel.font = DS.mono(9)
        captionLabel.textColor = DS.textFaint
        captionLabel.alignment = .right
        // 12 + 120 + 2 + the caption's 102 + 12 fill the 248 pt slot; should
        // the caption ever be wider, it, not the picker, gives way.
        captionLabel.setContentCompressionResistancePriority(
            NSLayoutConstraint.Priority(740), for: .horizontal)
        captionLabel.setAccessibilityIdentifier("scopes.\(name).caption")
        for readout in [highlights, shadows] {
            readout.font = DS.mono(11)
            readout.textColor = DS.textMuted
        }
        highlights.setAccessibilityIdentifier("scopes.\(name).highlights")
        shadows.setAccessibilityIdentifier("scopes.\(name).shadows")
        for view in [picker, captionLabel, highlights, shadows] as [NSView] {
            view.translatesAutoresizingMaskIntoConstraints = false
            addSubview(view)
        }
        let inset = Self.inset
        let height = heightAnchor.constraint(equalToConstant: 0)
        let top = highlights.topAnchor.constraint(equalTo: topAnchor)
        heightConstraint = height
        readoutTop = top
        NSLayoutConstraint.activate([
            height, top,
            picker.topAnchor.constraint(equalTo: topAnchor, constant: Self.headerTop),
            picker.leadingAnchor.constraint(equalTo: leadingAnchor, constant: inset),
            captionLabel.centerYAnchor.constraint(equalTo: picker.centerYAnchor),
            captionLabel.trailingAnchor.constraint(equalTo: trailingAnchor, constant: -inset),
            captionLabel.leadingAnchor.constraint(
                greaterThanOrEqualTo: picker.trailingAnchor, constant: 2),
            highlights.leadingAnchor.constraint(equalTo: leadingAnchor, constant: inset),
            highlights.heightAnchor.constraint(equalToConstant: Self.readoutHeight),
            shadows.topAnchor.constraint(
                equalTo: highlights.bottomAnchor, constant: Self.readoutGap),
            shadows.leadingAnchor.constraint(equalTo: leadingAnchor, constant: inset),
            shadows.heightAnchor.constraint(equalToConstant: Self.readoutHeight),
        ])
    }

    /// The picked kind's body in place of the last one, empty until a trace.
    private func installBody() {
        NSLayoutConstraint.deactivate(bodyConstraints)
        body.removeFromSuperview()
        switch kind {
        case .waveform:
            let waveform = WaveformTraceView()
            waveform.signal = signal
            body = waveform
        case .parade:
            let parade = ParadeView()
            parade.signal = signal
            body = parade
        case .vectorscope:
            let vectorscope = VectorscopeView()
            vectorscope.signal = signal
            vectorscope.zoom = zoom
            vectorscope.onZoom = { [weak self] zoom in self?.onZoom?(zoom) }
            vectorscope.cells.setAccessibilityIdentifier("scopes.\(name).zoom")
            body = vectorscope
        case .histogram: body = HistogramView()
        }
        body.setAccessibilityIdentifier("scopes.\(name).trace")
        body.translatesAutoresizingMaskIntoConstraints = false
        addSubview(body)
        let top = Self.headerTop + DS.controlHeight + Self.gap
        if kind == .vectorscope {
            bodyConstraints = [
                body.topAnchor.constraint(equalTo: topAnchor, constant: top),
                body.centerXAnchor.constraint(equalTo: centerXAnchor),
                body.widthAnchor.constraint(equalToConstant: 0),
                body.heightAnchor.constraint(equalToConstant: 0),
            ]
        } else {
            bodyConstraints = [
                body.topAnchor.constraint(equalTo: topAnchor, constant: top),
                body.leadingAnchor.constraint(equalTo: leadingAnchor, constant: Self.inset),
                body.trailingAnchor.constraint(equalTo: trailingAnchor, constant: -Self.inset),
                body.heightAnchor.constraint(equalToConstant: 0),
            ]
        }
        NSLayoutConstraint.activate(bodyConstraints)
        highlights.isHidden = !Self.hasReadouts(kind)
        shadows.isHidden = !Self.hasReadouts(kind)
        captionLabel.stringValue = signal.caption(for: kind)
        show(nil)
        picker.refresh()
        applyHeights()
    }

    /// The slot's, the body's and the readouts' heights for `bodyHeight`.
    private func applyHeights() {
        let side = kind == .vectorscope ? min(Self.bodyWidth, bodyHeight) : bodyHeight
        for constraint in bodyConstraints where constraint.firstAttribute == .height
            || constraint.firstAttribute == .width
        {
            constraint.constant = side
        }
        heightConstraint?.constant = Self.chromeHeight(for: kind) + bodyHeight
        readoutTop?.constant =
            Self.headerTop + DS.controlHeight + Self.gap + bodyHeight + Self.gap
    }
}

#if FRAMEJOB_DEV_TOOLS
extension ScopeSlotView: UISnapshotParts {
    /// The picker draws its item itself, so the layout dump names it:
    /// `scopes.<top|bottom>.picker`, its text the pick's title; and with a
    /// vectorscope body, `scopes.<top|bottom>.zoom`, its text the zoom ("4×")
    /// and its rect the three cells'.
    func snapshotParts() -> [UISnapshotPart] {
        var parts = [
            UISnapshotPart(id: "scopes.\(name).picker", text: kind.title, rect: picker.frame)
        ]
        if let vectorscope = body as? VectorscopeView {
            parts.append(UISnapshotPart(
                id: "scopes.\(name).zoom", text: "\(zoom)×",
                rect: vectorscope.cells.convert(vectorscope.cells.bounds, to: self)))
        }
        return parts
    }
}
#endif
import AppKit

/// What `ScopesPanelView.layout(picks:paneHeight:)` answers: whether the
/// bottom slot shows, and one body height per shown slot, top first.
struct ScopeSlotLayout: Equatable {
    let showsBottom: Bool
    let bodyHeights: [CGFloat]
}

/// View ▸ Scopes' panel (spec §11 GR-5, GR-10): a fixed 248 pt column at the
/// pane's right edge, its full height, holding two stacked slots, each with a
/// picker. Off, it is zero wide and hidden and the canvas takes the pane. Its
/// contents are a 248 pt block pinned to its leading edge and clipped, so a
/// zero width never asks a constraint for a negative one. Shown, its window's
/// tap (`WaveformTaps`) is attached with the passes its visible slots show —
/// one pass per kind and zoom, so one scope in both slots costs one, and two
/// vectorscopes at different zooms two (spec §11 GR-31) — and hidden, or out
/// of its window, detached.
///
/// **The layout rule** (owner, 2026-10-10, GR-10 as amended in G2-1): when
/// the pane cannot hold both slots' bodies at their preferred heights, both
/// shrink by one factor to fit, the vectorscope square and centred; below
/// `twoSlotMinHeight` only the top slot shows. A layout pass that shows or
/// hides the bottom slot, and every pick and zoom, re-attach the tap with
/// the new passes and ask for a frame (`onNeedsFrame`), so no slot waits
/// empty.
///
/// **Nothing here persists** (GR-5, GR-10, GR-31): a new window starts with
/// the panel off, the picks at `openingPicks` and every zoom ×1; a pick or a
/// zoom lasts while the window is open (a zoom across a pick of another scope
