301	extension InspectorBinding {
302	    /// The `"group.key"` paths a list of ops writes: `set_video`, `set_audio`
303	    /// and `set_text` by their patch's keys, `set_graphic` and an end's
304	    /// `graphic` by `graphicPaths`, `set_action_end` by each group of its
305	    /// patch, and `set_speed` by `speed`, the end's top-level rate key (spec
306	    /// §11 SR-21 (c)); every other op (a trim, a reverse) writes none.
307	    static func paths(of ops: [ReelOp]) -> [String] {
308	        let groups = ["set_video": "video", "set_audio": "audio", "set_text": "text"]
309	        var found = Set<String>()
310	        for op in ops {
311	            if op.name == "set_speed" {
312	                found.insert("speed")
313	                continue
314	            }
315	            guard let patch = op.args["patch"] as? [String: Any] else { continue }
316	            if let group = groups[op.name] {
317	                found.formUnion(patch.keys.map { group + "." + $0 })
318	            } else if op.name == "set_action_end" {
319	                found.formUnion(paths(inPatch: patch))
320	                found.formUnion(op.args["off"] as? [String] ?? [])  // keyed OFF (CI-14)
321	            } else if op.name == "set_graphic" { found.formUnion(graphicPaths(patch)) }
322	        }
323	        return found.sorted()
324	    }
325	
326	    /// An end patch's paths, spelled as `paths(of:)` spells them: a top-level
327	    /// key that is not a group — `speed` (spec §11 SR-21 (c)) — by its own
328	    /// name.
329	    private static func paths(inPatch patch: [String: Any]) -> [String] {
330	        patch.flatMap { group, value -> [String] in
331	            if group == "graphic" { return graphicPaths(value) }
332	            guard let fields = value as? [String: Any] else { return group == "speed" ? [group] : [] }
333	            return fields.keys.map { group + "." + $0 }
334	        }
335	    }
336	
337	    /// A `graphic` group's paths, `set_graphic`'s patch or an end's (spec §11
338	    /// G-34 (l)): `graphic.props.<key>` per prop, none for the core's
339	    /// `kinds`, and `graphic.<key>` for any other key — `set_graphic`'s
340	    /// `width`, `height` and `length`, which no end takes, so their rows are
341	    /// ⊘ while an action is selected.
342	    private static func graphicPaths(_ group: Any) -> [String] {
343	        guard let body = group as? [String: Any] else { return [] }
344	        var paths: [String] = []
345	        for (key, value) in body where key != "kinds" {
346	            if key == "props" {
347	                let props = (value as? [String: Any])?.keys.map { "graphic.props." + $0 }
348	                paths += props ?? []
349	            } else {
350	                paths.append("graphic." + key)
351	            }
352	        }
353	        return paths
354	    }
355	
356	    /// Whether any of the ops reaches an action's end patch.
357	    static func animates(_ ops: [ReelOp]) -> Bool {
358	        ops.contains { $0.name == "set_action_end" }
359	    }
360	
361	    /// The selected action's end patch, as paths.
362	    func keyedPaths() -> Set<String> {
363	        guard let action = selectedAction else { return [] }
364	        return Set(Self.paths(inPatch: action.end.dictionary))
365	    }
366	
367	    /// The time-order numbers of the single selected clip's OTHER actions
368	    /// whose end patch holds any of `paths`. One clip only: an action's
369	    /// number is its clip's, and two clips' numbers would say nothing.
370	    func otherActions(keying paths: [String]) -> [Int] {
371	        guard isSingle, let clip = primary, !paths.isEmpty else { return [] }
372	        let wanted = Set(paths)
373	        let selected = selectedAction?.id
374	        return ActionBands.ordered(clip).enumerated().compactMap { index, action in
375	            guard action.id != selected,
376	                  !wanted.isDisjoint(with: Self.paths(inPatch: action.end.dictionary))
377	            else { return nil }
378	            return index + 1
379	        }
380	    }
381	
382	    /// The selected action's time-order NUMBER on the single selected clip
383	    /// (`ActionBands.ordered`), nil with none selected.
384	    var selectedActionNumber: Int? {
385	        guard let id = selectedAction?.id, let clip = primary else { return nil }
386	        return ActionBands.ordered(clip).firstIndex { $0.id == id }.map { $0 + 1 }
387	    }
388	
389	    /// The id of the single selected clip's action numbered `number`.
390	    func actionID(number: Int) -> UInt32? {
391	        guard isSingle, let clip = primary else { return nil }
392	        let ordered = ActionBands.ordered(clip)
393	        return ordered.indices.contains(number - 1) ? ordered[number - 1].id : nil
394	    }
395	
396	    /// ONE `set_action_end` that nulls every `"group.key"` of `paths` in the
397	    /// selected action's end patch — a null REMOVES the key (spec §11 CI-9),
398	    /// so the value falls back to what was held. A one-part path (`speed`,
399	    /// spec §11 SR-21 (c)) is nulled at the patch's top. Nothing without a
400	    /// selected action on a single clip, or without a path.
401	    func clearOps(_ paths: Set<String>) -> [ReelOp] {
402	        guard let action = selectedAction, isSingle, let clip = primary, !paths.isEmpty
403	        else { return [] }
404	        var patch: [String: Any] = [:]
405	        for path in paths.sorted() {
406	            let parts = path.split(separator: ".", maxSplits: 1).map(String.init)
407	            if parts.count == 1 {
408	                patch[parts[0]] = NSNull()
409	                continue
410	            }
411	            guard parts.count == 2 else { continue }
412	            var group = patch[parts[0]] as? [String: Any] ?? [:]
413	            if parts[0] == "graphic", parts[1].hasPrefix("props.") {
414	                // An end's prop nests one level deeper (G-34 (a)).
415	                var props = group["props"] as? [String: Any] ?? [:]
416	                props[String(parts[1].dropFirst("props.".count))] = NSNull()
417	                group["props"] = props
418	            } else {
419	                group[parts[1]] = NSNull()
420	            }
421	            patch[parts[0]] = group
422	        }
423	        guard !patch.isEmpty else { return [] }
424	        return [.setActionEndRaw(clip: clip.id, action: action.id, patch: patch)]
425	    }
426	
427	    /// Spec §11 CI-7's rule, in its order.
428	    func mark(writes: [String], follows: [String], animates: Bool, discrete: Bool) -> RowMark {
429	        if writes.isEmpty && follows.isEmpty { return .none }
430	        if selectedAction != nil {
431	            if !writes.isEmpty && !animates { return .notAnimatable }
432	            let keyed = keyedPaths()
433	            if !keyed.isDisjoint(with: writes) { return discrete ? .keyedAtEnd : .keyed }
434	            if !keyed.isDisjoint(with: follows) { return .follows }
435	        }
436	        if let number = otherActions(keying: writes + follows).first { return .other(number) }
437	        return .none
438	    }
439	
440	    /// The value `read` answers at the PLAYHEAD, when the playhead is inside
441	    /// the first selected clip; nil otherwise.
442	    func nowValue(_ read: () -> Double) -> Double? {
443	        guard let clip = primary, clip.start <= playhead, playhead < clip.end else { return nil }
444	        return at(.playhead, read)
445	    }
446	
447	    /// The value `read` answers at the selected action's START; nil with no
448	    /// action selected.
449	    func startValue(_ read: () -> Double) -> Double? {
450	        guard selectedAction != nil else { return nil }
451	        return at(.start, read)
452	    }
453	}
