456	/// One sub-tab of the Clip tab (spec §11 CI-5). The case order is the display
457	/// order: Text and Shape come first for those kinds, Clip is always last.
458	enum ClipSubTab: String, CaseIterable {
459	    case text, shape, graphic, picture, color, sound, clip
460	
461	    var title: String {
462	        switch self {
463	        case .text: return "Text"
464	        case .shape: return "Shape"
465	        case .graphic: return "Graphic"
466	        case .picture: return "Picture"
467	        case .color: return "Color"
468	        case .sound: return "Sound"
469	        case .clip: return "Clip"
470	        }
471	    }
472	
473	    /// The `◆N` badge (spec §11 CI-6): how many KEYS of an action's end patch
474	    /// this tab's sections write. Motion lives on Clip, so Picture counts the
475	    /// video keys without it; a shape's props are not animatable; Graphic
476	    /// counts the end's `graphic.props`, a key its module no longer declares
477	    /// included (CI-6 amended, G-34 (l)). Color counts `color`, one key
478	    /// however many of its thirteen the end names, and Picture no longer does
479	    /// (CI-6 amended by GR-2); for an all-adjustment selection (`adjustment`)
480	    /// it also counts `opacity`, the Adjustment section's Strength (GR-6). An
481	    /// end's `look` is Color's too, one key (GR-7), and so is its `wheels`,
482	    /// one key however many of its nine it names (GR-11), and its `curves`,
483	    /// one key however many channels it names (GR-12), and its `qualifier`,
484	    /// one key however many ranges it names (GR-13); Picture counts none of
485	    /// them. Clip also counts an end's `speed`, the Speed section's Rate (CI-6
486	    /// amended by SR-21).
487	    func keyedCount(in end: ActionPatch, adjustment: Bool = false) -> Int {
488	        switch self {
489	        case .text: return end.text?.dictionary.count ?? 0
490	        case .shape: return 0
491	        case .graphic: return end.graphic?.props.count ?? 0
492	        case .picture:
493	            let other: Set<String> = ["motion", "color", "look", "wheels", "curves", "qualifier"]
494	            return end.video?.dictionary.keys.filter { !other.contains($0) }.count ?? 0
495	        case .color:
496	            return (end.video?.color?.isEmpty == false ? 1 : 0)
497	                + (end.video?.dictionary["look"] != nil ? 1 : 0)
498	                + (end.video?.wheels?.isEmpty == false ? 1 : 0)
499	                + (end.video?.curves?.isEmpty == false ? 1 : 0)
500	                + (end.video?.qualifier?.isEmpty == false ? 1 : 0)
501	                + (adjustment && end.video?.dictionary["opacity"] != nil ? 1 : 0)
502	        case .sound: return end.audio?.dictionary.count ?? 0
503	        case .clip:
504	            return (end.video?.dictionary["motion"] == nil ? 0 : 1) + (end.speed == nil ? 0 : 1)
505	        }
506	    }
507	}
