509	/// The strip of sub-tabs under the action lane: equal square cells whose 1 pt
510	/// borders collapse into one, the active cell in the selection fill with an
511	/// accent border, and a mint `◆N` after a label whose tab the selected action
512	/// keys. Built with its tabs and its active one, like `PanelTabsView`: a pick
513	/// goes out through `onSelect` and the pane is rebuilt with a new strip.
514	/// No hover — a mode switch is instant.
515	final class ClipSubTabsView: NSView, OptionControl {
516	    static let cell: CGFloat = 24, top: CGFloat = 8, bottom: CGFloat = 8
517	    private static let side = InspectorMetrics.inset
518	
519	    let tabs: [ClipSubTab]
520	    let active: ClipSubTab
521	    private let badge: (ClipSubTab) -> Int
522	    private let onSelect: (ClipSubTab) -> Void
523	    private var badges: [Int] = []
524	
525	    init(
526	        tabs: [ClipSubTab], active: ClipSubTab, badge: @escaping (ClipSubTab) -> Int,
527	        onSelect: @escaping (ClipSubTab) -> Void
528	    ) {
529	        self.tabs = tabs
530	        self.active = active
531	        self.badge = badge
532	        self.onSelect = onSelect
533	        super.init(frame: .zero)
534	        wantsLayer = true
535	        badges = tabs.map(badge)
536	    }
537	
538	    @available(*, unavailable)
539	    required init?(coder: NSCoder) {
540	        fatalError("ClipSubTabsView does not support NSCoder")
541	    }
542	
543	    override var isFlipped: Bool { true }
544	
545	    override var intrinsicContentSize: NSSize {
546	        NSSize(width: NSView.noIntrinsicMetric, height: Self.top + Self.cell + Self.bottom)
547	    }
548	
549	    /// Equal cells, each sharing its left border with the previous one's
550	    /// right (a −1 overlap), with `PanelTabsView.tabRect`'s rounding so the
551	    /// row tiles exactly.
552	    func cellRect(_ index: Int) -> CGRect {
553	        let step = (bounds.width - 2 * Self.side - 1) / CGFloat(max(tabs.count, 1))
554	        let left = Self.side + (CGFloat(index) * step).rounded()
555	        let right = Self.side + (CGFloat(index + 1) * step).rounded() + 1
556	        return CGRect(x: left, y: Self.top, width: right - left, height: Self.cell)
557	    }
558	
559	    /// Re-reads the badges; redraws only when they changed.
560	    func refresh() {
561	        let next = tabs.map(badge)
562	        guard next != badges else { return }
563	        badges = next
564	        needsDisplay = true
565	    }
566	
567	    override func mouseDown(with event: NSEvent) {
568	        let point = convert(event.locationInWindow, from: nil)
569	        guard let index = tabs.indices.first(where: { cellRect($0).contains(point) }),
570	              tabs[index] != active
571	        else { return }
572	        onSelect(tabs[index])
573	    }
574	
575	    override func draw(_ dirtyRect: NSRect) {
576	        DS.border.setFill()
577	        NSRect(x: 0, y: bounds.height - 1, width: bounds.width, height: 1).fill()
578	        // The active cell last, so its accent border wins the shared edges.
579	        let order = tabs.indices.filter { tabs[$0] != active }
580	            + tabs.indices.filter { tabs[$0] == active }
581	        for index in order {
582	            drawCell(index)
583	        }
584	    }
585	
586	    private func drawCell(_ index: Int) {
587	        let rect = cellRect(index)
588	        let isActive = tabs[index] == active
589	        (isActive ? DS.selectionFill : NSColor.controlBackgroundColor).setFill()
590	        rect.fill()
591	        (isActive ? DS.accent : DS.border).setStroke()
592	        NSBezierPath(rect: rect.insetBy(dx: 0.5, dy: 0.5)).stroke()
593	
594	        let label = NSAttributedString(
595	            string: tabs[index].title,
596	            attributes: [
597	                .font: DS.sans(11, weight: .semibold),
598	                .foregroundColor: isActive ? DS.textStrong : DS.textMuted,
599	            ])
600	        let count = badges.indices.contains(index) ? badges[index] : 0
601	        let mark = count > 0
602	            ? NSAttributedString(
603	                string: "◆\(count)",
604	                attributes: [.font: DS.mono(9, weight: .medium), .foregroundColor: DS.action])
605	            : nil
606	        let labelSize = label.size()
607	        let markSize = mark?.size() ?? .zero
608	        let gap: CGFloat = mark == nil ? 0 : 4
609	        let width = ceil(labelSize.width) + gap + ceil(markSize.width)
610	        let x = (rect.midX - width / 2).rounded()
611	        label.draw(at: NSPoint(x: x, y: rect.midY - labelSize.height / 2))
612	        mark?.draw(
