47	/// A row's default (spec §11 CI-9): the undo name its reset runs under,
48	/// whether the row differs from its default now, and the ops that put the
49	/// default back — on the base props, or on the selected action's end.
50	struct InspectorRowDefault {
51	    let name: String
52	    let differs: () -> Bool
53	    let ops: () -> [ReelOp]
54	
55	    /// The default a typed row derives from its own `read` and `ops`: the
56	    /// value `read` answers in `.defaults`, written through `ops`.
57	    static func derived<T: Equatable>(
58	        _ binding: InspectorBinding, name: String, read: @escaping () -> T,
59	        ops: @escaping (T) -> [ReelOp]
60	    ) -> InspectorRowDefault {
61	        InspectorRowDefault(
62	            name: name,
63	            differs: { [weak binding] in
64	                guard let binding else { return false }
65	                return read() != binding.at(.defaults, read)
66	            },
67	            ops: { [weak binding] in
68	                guard let binding else { return [] }
69	                return ops(binding.at(.defaults, read))
70	            })
71	    }
72	}
