97	        didSet {
98	            guard hovered != oldValue else { return }
99	            needsDisplay = true
100	            updateToolTip()
101	        }
102	    }
103	    /// The × — hover alone is not enough, the row must be keyed.
104	    var showsRemove: Bool { hovered && isKeyed }
105	
106	    init(
107	        binding: InspectorBinding?, writes: [ReelOp], follows: [ReelOp],
108	        label: InspectorRowLabel?, controls: [NSView], discrete: Bool,
109	        default: InspectorRowDefault?
