111	        self.writes = InspectorBinding.paths(of: writes)
112	        self.follows = InspectorBinding.paths(of: follows)
113	        self.binding = binding
114	        self.animates = InspectorBinding.animates(writes)
115	        self.default = `default`
116	        self.discrete = discrete
117	        self.label = label
118	        self.controls = controls
