132	    /// The keys this row writes that the selected action holds — what a
133	    /// section's `◆N` is the union of.
134	    func keyedWrites() -> Set<String> {
135	        guard let binding else { return [] }
136	        return binding.keyedPaths().intersection(writes)
137	    }
