139	    /// Takes the row's keys out of the selected action's end patch — the ×
140	    /// and the menu's "Remove from action N".
141	    func removeFromAction() {
142	        guard let binding else { return }
143	        binding.apply("Remove from Action", binding.clearOps(keyedWrites()))
144	    }
