618	/// The Clip tab's pinned block (the clip inspector handoff's "Pinned action
619	/// lane block", road map 9 §1 and §3): the selection header, the action lane
620	/// and the sub-tab strip, stacked, and under them the matte note when the
621	/// pane gives one (spec §11 MT-7, `ClipPane+Matte.swift`). One
622	/// `OptionControl`, because the pane has one header slot
623	/// (`InspectorPaneView.makeHeader()`), refreshed with it and hosted ABOVE the
624	/// scroll view by the controller (`pinnedBlock`).
625	final class ClipHeaderBlock: NSView, OptionControl {
626	    private let header: ClipSelectionHeaderView
627	    private let lane: ActionLaneView
628	    private let strip: ClipSubTabsView?
629	    private let noteLabel: InspectorNoteLabel?
630	
631	    /// `note` is given only while it has words: the pane's structure
632	    /// signature carries whether it shows, so its coming or going rebuilds
633	    /// the block, and a refresh only re-reads its words.
634	    init(
635	        binding: InspectorBinding, inspector: InspectorViewController?,
636	        subTabs: ClipSubTabsView?, note: (() -> String?)? = nil
637	    ) {
638	        header = ClipSelectionHeaderView(binding: binding)
639	        lane = ActionLaneView(binding: binding, inspector: inspector)
640	        strip = subTabs
641	        noteLabel = note.map { InspectorNoteLabel(wraps: true, note: $0) }
642	        super.init(frame: .zero)
643	        var views: [NSView] = [header, lane]
644	        if let subTabs { views.append(subTabs) }
645	        var above = topAnchor
646	        for view in views {
647	            view.translatesAutoresizingMaskIntoConstraints = false
648	            addSubview(view)
649	            NSLayoutConstraint.activate([
650	                view.topAnchor.constraint(equalTo: above),
651	                view.leadingAnchor.constraint(equalTo: leadingAnchor),
652	                view.trailingAnchor.constraint(equalTo: trailingAnchor),
653	            ])
654	            above = view.bottomAnchor
655	        }
656	        if let label = noteLabel {
657	            // A sentence of two lines at the panel's width: it wraps.
658	            label.translatesAutoresizingMaskIntoConstraints = false
659	            addSubview(label)
660	            NSLayoutConstraint.activate([
661	                label.topAnchor.constraint(equalTo: above, constant: 6),
662	                label.leadingAnchor.constraint(
663	                    equalTo: leadingAnchor, constant: InspectorMetrics.inset),
664	                label.trailingAnchor.constraint(
665	                    equalTo: trailingAnchor, constant: -InspectorMetrics.inset),
666	            ])
667	            label.bottomAnchor.constraint(equalTo: bottomAnchor, constant: -8).isActive = true
668	        } else {
669	            above.constraint(equalTo: bottomAnchor).isActive = true
670	        }
671	    }
