673	    @available(*, unavailable)
674	    required init?(coder: NSCoder) {
675	        fatalError("ClipHeaderBlock does not support NSCoder")
676	    }
677	
678	    override var isFlipped: Bool { true }
679	
680	    /// The lane, for a probe.
681	    var actionLane: ActionLaneView { lane }
682	
683	    /// The sub-tab strip, for a probe.
684	    var subTabsView: ClipSubTabsView? { strip }
685	
686	    /// The matte note's words as shown, for a probe; nil when it has none.
687	    var noteText: String? { noteLabel.flatMap { $0.isHidden ? nil : $0.stringValue } }
688	
689	    func refresh() {
690	        header.refresh()
691	        lane.refresh()
692	        strip?.refresh()
693	        noteLabel?.refresh()
694	    }
695	}
