20	    /// Copies one payload clip's property groups onto every named clip (spec
21	    /// §6) — Edit ▸ Paste Attributes. The clip is the EARLIEST, then the
22	    /// front-most (`track` is a depth, 0 = front), then the lower id: Copy
23	    /// writes a selection in storage — creation — order, not the timeline's,
24	    /// so the array's first is a clip the user cannot see. Which fields
25	    /// travel, which a target keeps and why a group is replaced rather than
26	    /// merged are the module doc's.
27	    ///
28	    /// `groups` absent means every one of the four LAYER groups both sides
29	    /// have, silently skipping the rest: video onto a text clip from a media
30	    /// clip copies the video, leaves the text alone and drops the audio,
31	    /// which has nowhere to go. `graphic` is never in that set, and
32	    /// `skip_missing` changes nothing there. A NAMED group is different —
33	    /// one the source lacks is an `Err` naming the group, one a target lacks
34	    /// is `Err("clip N has no audio properties")`, the patches' answer, and
35	    /// `graphic` onto a clip drawn by another module is an `Err` naming both
36	    /// modules — because a caller who asked for it would otherwise never
37	    /// learn it did not happen. With `skip_missing` a caller says it does
38	    /// not need to: a named group the source lacks is dropped and a target
39	    /// that cannot take one is skipped for it (G-32). An empty explicit
40	    /// list, an identity paste and an empty selection are all identities.
41	    /// The copied layer groups then pass the range checks a patch does, so a
42	    /// payload written by hand cannot smuggle in a value the inspector would
43	    /// refuse; copied graphic props pass the shape check, the first time a
44	    /// target takes them.
45	    pub fn paste_attributes(
46	        &self,
47	        clips: &[u32],
48	        payload: &Value,
49	        groups: Option<&[PasteGroup]>,
50	        skip_missing: bool,
51	    ) -> Result<Outcome, String> {
52	        let payload = parse_payload(payload)?;
53	        let earliest = |c: &&Clip| (c.start, c.track, c.id);
54	        let Some(source) = payload.clips.iter().min_by_key(earliest) else {
55	            return Err("paste payload has no clips".to_string());
56	        };
57	        let mut named: Option<Vec<PasteGroup>> = None;
58	        if let Some(asked) = groups {
59	            let mut kept = Vec::new();
60	            for group in asked {
61	                if has(source, *group) {
62	                    kept.push(*group);
63	                } else if !skip_missing {
64	                    return Err(format!("payload clip has no {} properties", group.name()));
65	                }
66	            }
67	            named = Some(kept);
68	        }
69	        let ids: Vec<u32> = self.selected_clips(clips)?.iter().map(|c| c.id).collect();
70	
71	        let mut next = self.clone();
72	        // Read at most once, by the first target that takes it (G-32 (f)).
73	        let mut copied: Option<Map<String, Value>> = None;
74	        // The source with its looks pointing at THIS project's LUTs, made by
75	        // the first target that takes the video group (spec §11 GR-8): the
76	        // LUTs it names are absorbed by path, as `paste` absorbs media, and
77	        // an id the payload lacks becomes no look.
78	        let mut looked: Option<Clip> = None;
79	        for id in ids {
80	            let Some(mut target) = next.clip(id).cloned() else {
81	                continue;
82	            };
83	            let chosen: Vec<PasteGroup> = match &named {
84	                Some(named) => named.clone(),
85	                None => GROUPS
86	                    .into_iter()
87	                    .filter(|g| has_group(source, *g) && has_group(&target, *g))
88	                    .map(PasteGroup::of)
89	                    .collect(),
90	            };
91	            let takes_video = chosen.contains(&PasteGroup::Video) && target.video.is_some();
92	            if takes_video && looked.is_none() {
93	                let looks = [
94	                    look_media_ids(source),
95	                    hide_silent_media(source).into_iter().collect(),
96	                ];
97	                let map = absorb_media(&mut next, &payload, &[], &looks.concat())?;
98	                let mut copy = source.clone();
99	                remap_look_media(&mut copy, &map);
100	                remap_hide_silent(&mut copy, &map);
101	                looked = Some(copy);
102	            }
103	            let from = looked.as_ref().unwrap_or(source);
104	            for group in chosen {
105	                if !has(&target, group) {
106	                    if skip_missing {
107	                        continue;
108	                    }
109	                    return Err(format!("clip {id} has no {} properties", group.name()));
110	                }
111	                let Some(layer) = group.layer() else {
112	                    let keep: Vec<String> = target.graphic.as_ref().map_or_else(Vec::new, |g| {
113	                        let named = g.props.keys().filter(|key| names_prop(&target, key));
114	                        named.cloned().collect()
115	                    });
116	                    let (Some(from), Some(into)) = (graphic_of(from), target.graphic.as_mut())
117	                    else {
118	                        continue;
119	                    };
120	                    if into.name != from.name {
121	                        if skip_missing {
122	                            continue;
123	                        }
124	                        return Err(format!(
125	                            "clip {id} is drawn by \"{}\" and the payload clip by \"{}\"; \
126	                             graphic props are pasted only between clips of one module",
127	                            into.name, from.name
128	                        ));
129	                    }
130	                    if copied.is_none() {
131	                        copied = Some(checked_props(from)?);
132	        selectClips(addedSince: before, in: document)
133	    }
