216	    /// mine" and leaves the base file's answer alone.
217	    func validateClipboardAction(
218	        _ action: Selector, pasteboard: NSPasteboard = .general
219	    ) -> Bool? {
220	        guard let document = document else { return false }
221	        switch action {
222	        case #selector(cut(_:)), #selector(copy(_:)):
223	            return !document.selection.isEmpty
224	        case #selector(paste(_:)):
225	            return canPasteClips(on: pasteboard)
226	        case #selector(pasteAttributes(_:)):
227	            // Paste needs no selection (the clips land at the playhead);
228	            // Paste Attributes needs something to paste ONTO.
