232	            // copied is not read here (the bytes, on every menu validation):
233	            // a copied clip that is not a graphic is the item's beep (G-32).
234	            return canPasteClips(on: pasteboard)
235	                && selectedClips.contains { $0.source == .graphic && $0.graphic != nil }
